# Now apply to data
concept_index = {c['id']: i for i, c in enumerate(data['concepts'])}

results = []
for cid, upd in updates.items():
    if cid not in concept_index:
        results.append(f"id={cid} NOT FOUND")
        continue
    idx = concept_index[cid]
    c = data['concepts'][idx]
    old_len = len(c.get('essay', ''))
    for k, v in upd.items():
        c[k] = v
    new_len = len(c.get('essay', ''))
    results.append(f"id={cid} ({c['name']}): {old_len} -> {new_len} chars")

with open('data/prototype_data.json', 'w') as f:
    json.dump(data, f, indent=2, ensure_ascii=False)

print("Update complete:")
for r in results:
    print(r)
